219	            case IN_TRANSIT -> newStatus == IN_INSPECTION;
220	            case IN_INSPECTION -> newStatus == FAILED_INSPECTION || newStatus == IN_STORAGE;
221	            case IN_STORAGE -> newStatus == ON_AUCTION || newStatus == AUCTION_EXPIRED || newStatus == SELLING;
222	            case ON_AUCTION -> newStatus == SOLD || newStatus == AUCTION_EXPIRED;
223	            case SELLING -> newStatus == SOLD || newStatus == AUCTION_EXPIRED || newStatus == ON_AUCTION;
224	            case SOLD, AUCTION_EXPIRED, FAILED_INSPECTION -> false;
225	        };
226	    }
